async function scene(kind,onPick){const seq=++loadSeq;view?.dispose();view=null;stage.replaceChildren();stage.className=kind==='intro'?'intro':'';const loading=document.createElement('div');loading.className='stage-message';loading.textContent='Opening the study…';stage.append(loading);try{const v=await makeScene(stage,{kind,onPick});if(seq!==loadSeq){v.dispose();return null}view=v;loading.remove();window.RanchView?.register('toy-world-review',()=>({study:id,level:study.level,interaction:context}),()=>v.renderer.render(v.scene,v.camera));return v}catch(e){loading.textContent='This 3D study could not load. Reload to try again.';console.error(e);return null}}
