async function fetchNotes(more=false){try{const u='/api/feedback?studyId='+encodeURIComponent('toy-world-'+id)+(more&&cursor?'&before='+encodeURIComponent(cursor):'');const r=await fetch(u,{credentials:'same-origin',cache:'no-store'});if(r.status===401){$('#sign-in').hidden=false;throw Error('Sign in to load and save shared notes. Your draft stays here.')}if(!r.ok)throw Error('Could not load shared notes. Try Refresh.');const data=await r.json();$('#sign-in').hidden=true;if(!more)$('#saved-notes').replaceChildren();$('#load-more')?.remove();for(const item of data.items||[])if(!document.querySelector(`[data-id="${item.id}"]`))$('#saved-notes').append(noteNode(item));cursor=data.nextBefore;$('#note-count').textContent=document.querySelectorAll('.saved-note').length;if(cursor){const b=button('Load older notes',()=>fetchNotes(true),'quiet');b.id='load-more';$('#saved-notes').append(b)}$('#note-status').textContent=data.items?.length?'Shared notes loaded.':'Your first note will appear here.'}catch(e){$('#note-status').textContent=e.message}}
$('#refresh-notes').onclick=()=>fetchNotes();
$('#note-form').onsubmit=async e=>{e.preventDefault();const note=$('#new-note').value.trim();if(!note||saving)return;saving=true;$('#new-note').disabled=true;$('#save-note').disabled=true;$('#note-status').textContent='Saving to the shared feedback inbox…';noteRequest||=Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(4)),b=>b.toString(16).padStart(2,'0')).join('');local.write(requestKey,noteRequest);try{const r=await fetch('/api/feedback',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({note,buildId:release.buildId,sha:release.sha,requestId:noteRequest,studyId:'toy-world-'+id,studyContext:context,studyLevel:study.level,page:location.href,title:study.title,entryId:'toy-world-review-20261024',threadTitle:'Abbie’s World study review',viewport:`${innerWidth}x${innerHeight}`})});if(r.status===401){$('#sign-in').hidden=false;throw Error('Sign in to save. Your note is still here.')}if(!r.ok)throw Error('Not saved yet. Your draft is safe here; tap Save to retry.');await r.json();$('#new-note').value='';local.write(noteKey,'');local.write(requestKey,null);noteRequest=null;$('#draft-state').textContent='';await fetchNotes();$('#note-status').textContent='Saved · visible to the app and project feedback inbox.'}catch(e){$('#note-status').textContent=e.message}finally{saving=false;$('#new-note').disabled=false;$('#save-note').disabled=false}};
